// r403: the Windows screen readers, as check boxes. r407: NVDA speaks already in Windows Setup.
// Setup's WinPE runs no 32-bit programs, so NVDA's installer (a 32-bit launcher) cannot unpack
// itself there ("side-by-side configuration is incorrect", r406), and it lacks four system
// libraries NVDA binds. Charon therefore puts on the media its own unpacker and stand-ins
// (src/windows, NvdaSetupOntoMedia below); the answer file starts them, and Narrator speaks when
// NVDA cannot. NVDA is installed at the first logon, which happens by itself (its installer fails
// in the specialize pass: tried); JAWS is installed at the
// first logon (Polish: the Altix installer if the user put one in
// \charon\readers, else the JAWS of Freedom Scientific); Narrator is built in.
inline const Choice windowsReaders[]={
    {u"NVDA, mówi już w instalatorze Windows",u"NVDA, speaks in Windows Setup already","nvda"},
    {u"JAWS: polska wersja od Altixa, inne języki od Freedom Scientific; bez licencji działa 40 minut od każdego uruchomienia Windows",
     u"JAWS: the Polish version from Altix, other languages from Freedom Scientific; without a licence it runs for 40 minutes after each Windows start","jaws"},
    {u"Narrator, wbudowany w Windows",u"Narrator, built into Windows","narrator"}};
