        // NarratorAfterSigninResetCompleted (r405). That happened after Charon-Readers.ps1 had put
        // NVDA on the list: NVDA spoke at the first desktop and never again by itself (measured).
        // With the mark already in the default user's registry the new account is left alone.
        RunCommand(x,order++,"reg.exe load HKU\\CharonDefault C:\\Users\\Default\\NTUSER.DAT");
        RunCommand(x,order++,"reg.exe add \"HKU\\CharonDefault\\Software\\Microsoft\\Windows NT\\CurrentVersion\\Accessibility\" /v NarratorAfterSigninResetCompleted /t REG_DWORD /d 1 /f");
        RunCommand(x,order++,"reg.exe unload HKU\\CharonDefault");
